import{$ as e,Dt as t,Y as n,ht as r,it as i,nt as a,o,rt as s,tt as c,yt as l}from"./chunks/framework.BDx6F-5s.js";var u=JSON.parse(`{"title":"Enterprise Security & Governance | SyncCrawl","description":"SSRF protection, air-gapped on-premise deployment, private LLM integrations, granular RBAC, and audit trails.","frontmatter":{"title":"Enterprise Security & Governance | SyncCrawl","description":"SSRF protection, air-gapped on-premise deployment, private LLM integrations, granular RBAC, and audit trails.","sort":5,"head":[["link",{"rel":"canonical","href":"https://empasy.io/docs/en/synccrawl/enterprise-security-governance.html"}]]},"headers":[],"relativePath":"en/synccrawl/enterprise-security-governance.md","filePath":"en/synccrawl/enterprise-security-governance.md","lastUpdated":1787441667000}`),d={name:`en/synccrawl/enterprise-security-governance.md`};function f(o,u,d,f,p,m){let h=l(`Mermaid`);return r(),c(`div`,null,[u[2]||=a(`<h1 id="enterprise-security-governance" tabindex="-1">Enterprise Security &amp; Governance <a class="header-anchor" href="#enterprise-security-governance" aria-label="Permalink to “Enterprise Security &amp; Governance”">​</a></h1><p>Security and compliance are essential when operating web crawlers within enterprise infrastructure. SyncCrawl incorporates multi-layered controls to safeguard against unauthorized network exploration and data exposure.</p><hr><h2 id="ssrf-server-side-request-forgery-defense" tabindex="-1">SSRF (Server-Side Request Forgery) Defense <a class="header-anchor" href="#ssrf-server-side-request-forgery-defense" aria-label="Permalink to “SSRF (Server-Side Request Forgery) Defense”">​</a></h2><p>Web crawlers execute network requests to external targets. Without proper validation, unauthorized requests to private IP spaces or cloud metadata endpoints (<code>169.254.169.254</code>) could pose security risks.</p><p>SyncCrawl implements the <strong><code>BrowserNavigateUrlValidator</code></strong> module to enforce URL filtering policies:</p>`,6),(r(),e(n,null,{default:t(()=>[i(h,{id:`mermaid-16`,class:`mermaid`,graph:`graph%20TD%0A%20%20%20%20REQ%5BCrawl%20URL%20Target%20Input%5D%20--%3E%20VAL%7BBrowserNavigateUrlValidator%7D%0A%20%20%20%20%0A%20%20%20%20VAL%20--%3E%7C1.%20Loopback%20Block%7C%20DROP1%5BBlock%20127.0.0.1%20%2F%20localhost%5D%0A%20%20%20%20VAL%20--%3E%7C2.%20RFC%201918%20Block%7C%20DROP2%5BBlock%2010.0.0.0%2F8%2C%20172.16.0.0%2F12%2C%20192.168.0.0%2F16%5D%0A%20%20%20%20VAL%20--%3E%7C3.%20Cloud%20Metadata%20Block%7C%20DROP3%5BBlock%20169.254.169.254%20AWS%2FAzure%20Meta%5D%0A%20%20%20%20VAL%20--%3E%7C4.%20Non-Standard%20Scheme%20Block%7C%20DROP4%5BBlock%20file%3A%2F%2F%2C%20gopher%3A%2F%2F%2C%20ftp%3A%2F%2F%5D%0A%20%20%20%20VAL%20--%3E%7C5.%20DNS%20Rebinding%20Check%7C%20DROP5%5BInspect%20resolved%20IP%20prior%20to%20socket%20connection%5D%0A%20%20%20%20%0A%20%20%20%20VAL%20--%3E%7CAll%20Checks%20Passed%7C%20PERMIT%5BAllow%20Safe%20External%20Web%20Navigation%5D%0A`})]),fallback:t(()=>[...u[0]||=[s(` Loading... `,-1)]]),_:1})),u[3]||=a(`<h3 id="key-ssrf-security-controls" tabindex="-1">Key SSRF Security Controls <a class="header-anchor" href="#key-ssrf-security-controls" aria-label="Permalink to “Key SSRF Security Controls”">​</a></h3><ul><li><strong>Loopback &amp; Private Subnet Filtering</strong>: Prohibits requests to <code>localhost</code>, <code>127.0.0.1</code>, and RFC 1918 internal subnets.</li><li><strong>Cloud Metadata Shield</strong>: Restricts access to cloud instance metadata services (<code>169.254.169.254</code>).</li><li><strong>DNS Rebinding Verification</strong>: Resolves domain names and verifies the destination IP address prior to opening socket connections.</li><li><strong>Protocol Whitelist</strong>: Allows <code>http://</code> and <code>https://</code> schemes while excluding non-standard protocols (<code>file://</code>, <code>jar://</code>, <code>dict://</code>).</li></ul><hr><h2 id="air-gapped-network-on-premises-isolation" tabindex="-1">Air-Gapped Network &amp; On-Premises Isolation <a class="header-anchor" href="#air-gapped-network-on-premises-isolation" aria-label="Permalink to “Air-Gapped Network &amp; On-Premises Isolation”">​</a></h2><p>SyncCrawl operates within isolated enterprise intranets:</p>`,5),(r(),e(n,null,{default:t(()=>[i(h,{id:`mermaid-49`,class:`mermaid`,graph:`graph%20TD%0A%20%20%20%20subgraph%20%22On-Premises%20Isolated%20Network%20(Air-Gapped)%22%0A%20%20%20%20%20%20%20%20CONSOLE%5Bsmart-crawling-console%5D%0A%20%20%20%20%20%20%20%20SERVER%5Bsmart-crawling-server%5D%0A%20%20%20%20%20%20%20%20AGENT%5Bsmart-crawling-agent%5D%0A%20%20%20%20%20%20%20%20%0A%20%20%20%20%20%20%20%20subgraph%20%22Internal%20AI%20Infrastructure%22%0A%20%20%20%20%20%20%20%20%20%20%20%20VLLM%5BPrivate%20LLMs%20-%20vLLM%20%2F%20Ollama%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20EMB%5BInternal%20Embeddings%20-%20BGE-M3%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20VDB%5B(Internal%20PGVector%20%2F%20Milvus)%5D%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20%0A%20%20%20%20%20%20%20%20CONSOLE%20--%3E%20SERVER%0A%20%20%20%20%20%20%20%20SERVER%20--%3E%20AGENT%0A%20%20%20%20%20%20%20%20SERVER%20--%3E%20VLLM%20%26%20EMB%20%26%20VDB%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20OUTSIDE((External%20Web%20%2F%20DMZ%20Proxy))%0A%20%20%20%20AGENT%20-.-%3E%7CEgress%20via%20Secure%20Forward%20Proxy%7C%20OUTSIDE%0A`})]),fallback:t(()=>[...u[1]||=[s(` Loading... `,-1)]]),_:1})),u[4]||=a(`<ul><li><strong>Private LLM Integration</strong>: Connects with on-premise <code>vLLM</code>, <code>Ollama</code>, or <code>LocalAI</code> instances to minimize data egress risks.</li><li><strong>DMZ Forward Proxy Support</strong>: Routes external web requests through designated enterprise forward proxies.</li><li><strong>Air-Gapped Registry Ready</strong>: Container images and dependencies can be served from private registries (Harbor, Nexus).</li></ul><hr><h2 id="granular-rbac-audit-trails" tabindex="-1">Granular RBAC &amp; Audit Trails <a class="header-anchor" href="#granular-rbac-audit-trails" aria-label="Permalink to “Granular RBAC &amp; Audit Trails”">​</a></h2><p>Crawling operations and knowledge searches are managed through role-based access control and logged for audit purposes:</p><h3 id="_1-role-based-access-control-rbac" tabindex="-1">1. Role-Based Access Control (RBAC) <a class="header-anchor" href="#_1-role-based-access-control-rbac" aria-label="Permalink to “1. Role-Based Access Control (RBAC)”">​</a></h3><ul><li><strong>Crawling Engineer (Admin)</strong>: Scenario authoring, Quartz schedule management, selector rule tuning.</li><li><strong>Business Analyst (Analyst)</strong>: Data exploration, RAG testing, report exporting.</li><li><strong>Compliance Officer (Auditor)</strong>: Access logs, egress traffic inspection, security policy monitoring.</li></ul><h3 id="_2-audit-trail-logging" tabindex="-1">2. Audit Trail Logging <a class="header-anchor" href="#_2-audit-trail-logging" aria-label="Permalink to “2. Audit Trail Logging”">​</a></h3><p>For every crawling execution, SyncCrawl records:</p><ul><li>Execution ID, requesting user identity, and client IP.</li><li>Requested URL and canonical destination URL after redirects.</li><li>Execution duration, HTTP status code, and response size.</li><li>SHA-256 hash of archived HTML snapshots.</li><li>Self-Healing diffs showing selector modifications.</li></ul>`,9)])}var p=o(d,[[`render`,f]]);export{u as __pageData,p as default};